"""Machine-level lemmas for 1RB0RA_1LC1LF_1RD0LB_1RA1LE_0LI0LC_1RG1LD_1LC1RH_0LH0RF_---0LA (all generated by mexp).
  python gen_machine_fh.py OUT.v    -> development file; machine_text() is used by gen_final_fh.py.
Writes cfgs_fh.pkl with every junction configuration (for the Definitions of the abstract part)."""
import sys, time, pickle
from pathlib import Path
from common import *
import mexp
from handloop import make_loop
import rules
from st0a import START as P0_START
from hop import XH, S1
from st0b import START as E0W
from mr import MR, S as MR_FIRST
from st2c import S2P, T2
from st3e import S3E, T3E
from st3y import Y, Y_START, Y_TARGET
from st3x import Y0z
SUB = engine.subst


def rule(name, s, t, pos=(), splits=0, progress=False):
    tree = mexp.explore(s, t, splits=splits, positive=frozenset(pos))
    g = mexp.Gen(name + '_')
    txt = mexp.rule_lemma(name, s, t, tree, g, progress=progress, positive=pos)
    return g.lemmas + [txt]


def gen():
    out, cfg = [], {}
    t0 = time.time()
    for name, s, t, pos in rules.ITEMS:
        out += rule('F' + name, s, t, pos, splits=2, progress=True)
    # P0: the exhausted list into the hop phase
    cfg['P0s'], cfg['S1'] = P0_START, S1
    out += rule('P0', P0_START, S1)
    P0b_s = SUB(S1, 'J', (('J', 1),), 1)
    P0b_t = SUB(SUB(XH('J', 'i'), 'i', (), 1), 'J', (('J', 1),), 0)
    cfg['P0b_s'], cfg['P0b_t'] = P0b_s, P0b_t
    out += rule('P0B', P0b_s, P0b_t)
    lp = make_loop(XH(), 'k', ['i'], ((('k', 1),), 0))
    g = mexp.Gen('HOP')
    hop_name, hop_binders = g.loop(lp)
    out += g.lemmas
    cfg['XH'] = XH()
    # P0c: 19 steps from the last hop boundary to the E0 configuration
    X0 = SUB(XH(), 'k', (), 0)
    c = X0
    for _ in range(19):
        c = pl.step(c)
    E0 = pickle.load(open('E0cfg.pkl', 'rb'))
    assert pl.canon(c) == pl.canon(E0)
    cfg['XH0'], cfg['E0'] = X0, E0
    out += rule('P0C', X0, E0)
    # P0d: E0 (r = 5w + 3) to the first macro-round configuration
    cfg['E0W'], cfg['MR'] = E0W, MR()
    out += rule('P0D', E0W, MR_FIRST)
    out += rule('MR1', SUB(MR(), 'w', (('w', 1),), 1), MR(d9=4, rz=8))
    MR0 = SUB(MR(), 'w', (), 0)
    P0e_t = KF(tok(1), tok(0), list(Z) * 7 + [run(Z, i=1)] + tok(7) + tok(6) + tok(8) + [V('l')])
    cfg['MR0'], cfg['P0e_t'] = MR0, P0e_t
    out += rule('P0E', MR0, P0e_t)
    # stage 2
    cfg['S2P'], cfg['T2'] = S2P, T2
    out += rule('ST2', S2P, T2)
    # stage 3
    cfg['S3E'], cfg['T3E'] = S3E, T3E
    out += rule('ST3E', S3E, T3E)
    cfg['Y'] = Y()
    out += rule('Y1', Y_START, Y_TARGET, pos=('a',), splits=6)
    X3 = SUB(Y0z(3), 'a', (('a', 1),), 21)
    tree = mexp.explore(X3, None, splits=0)
    assert tree.get('halt') and all(it[0] != 'split' for it in tree['items'])
    g = mexp.Gen('S3X')
    tac = ['intros.']
    for it in tree['items']:
        tac.append(g.stage(it[2], it[1], it[3]) if it[0] == 'ops' else g.use_loop(it[1]))
    end = tree['end']
    cn, vs = coqgen.free_vars(X3, end)
    out += g.lemmas
    out.append('Lemma ST3X : forall %s, %s -->* %s.\nProof.\n%s\n  finish_norm.\nQed.\n'
               % (' '.join(cn + vs), coqgen.cfg_coq(X3), coqgen.cfg_coq(end), coqgen.wrap(tac)))
    out.append('Lemma ST3X_halted : forall %s, halted tm (%s).\nProof. intros. reflexivity. Qed.\n'
               % (' '.join(cn + vs), coqgen.cfg_coq(end)))
    cfg['X3'], cfg['END'] = X3, end
    cfg['hop'] = (hop_name, hop_binders)
    pickle.dump(cfg, open('cfgs_fh.pkl', 'wb'))
    print('generated in %.1fs, %d lemmas; hop loop %s %s' % (time.time() - t0, len(out), hop_name, hop_binders), file=sys.stderr)
    return out


def machine_text():
    pl.LEMMAS.clear()
    lem = gen()
    return ('\n(** ** Crossing lemmas (generated) *)\n\n' + coqgen.crossing_lemmas()
            + '\n(** ** Machine-level lemmas (generated by mexp.py) *)\n\n' + '\n'.join(lem))


if __name__ == '__main__':
    text = header('fh machine part (development)') + '\n' + machine_text()
    Path(sys.argv[1]).write_text(text, newline='\n')
    print('wrote', sys.argv[1], len(text), 'bytes', file=sys.stderr)
